/**
 * \brief Patch the first recorded example of ISomething so that
 * the content of the element \p xml_name is replaced by \p text.
 */
std::string PatchTheFirstExample(
  const std::string& xml_name,
  const std::string& text
) {
  // NOTE (mristin):
  // FindFilesBySuffixRecursively answers a deque, and it is already sorted,
  // which is what the round-trip test above relies on as well.
  const std::deque<std::filesystem::path> paths(
    test::common::FindFilesBySuffixRecursively(
      DetermineXmlDir()
        / "Expected"
        / "something",
      ".xml"
    )
  );

  REQUIRE(!paths.empty());

  const std::string original(test::common::MustReadString(paths.front()));

  const std::size_t start(
    original.find(our::common::Concat("<", xml_name, ">"))
      + xml_name.size() + 2
  );
  const std::size_t end(
    original.find(our::common::Concat("</", xml_name, ">"))
  );

  return original.substr(0, start) + text + original.substr(end);
}

